import sys, os, json, csv, io


def norm_id(s):
    return str(s).strip().lower()


def norm_text(s):
    s = ''.join(c if c.isalnum() else ' ' for c in str(s).casefold())
    return ' '.join(s.split())


def read_batch(path):
    with open(path, encoding='utf-8', newline='') as f:
        text = f.read()
    meta = {}
    recs = []  # (ballot, contest, {rank: [marks]}) marks are ('c', id) or ('w', text)
    if path.endswith('.jsonl'):
        first = True
        for line in text.split('\n'):
            if not line.strip():
                continue
            o = json.loads(line)
            if first:
                meta = o
                first = False
                continue
            ranks = {}
            for m in o.get('marks', []):
                r = int(m['rank'])
                lst = ranks.setdefault(r, [])
                if m.get('write_in') is not None:
                    lst.append(('w', m['write_in']))
                else:
                    lst.append(('c', m['candidate']))
            recs.append((o.get('ballot'), o['contest'], ranks))
    else:
        lines = text.split('\n')
        i = 0
        while i < len(lines) and (lines[i].startswith('#') or not lines[i].strip()):
            l = lines[i]
            if l.startswith('#') and ':' in l:
                k, v = l[1:].split(':', 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
        rd = csv.reader(io.StringIO('\n'.join(lines[i:]), newline=''))
        header = None
        for row in rd:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [c.strip() for c in row]
                continue
            d = dict(zip(header, row))
            ranks = {}
            for h, v in zip(header, row):
                if h.startswith('rank') and h[4:].isdigit():
                    r = int(h[4:])
                    marks = []
                    if v.strip():
                        for p in v.split('|'):
                            if p.startswith('WI:'):
                                marks.append(('w', p[3:]))
                            elif p.strip():
                                marks.append(('c', p))
                    ranks[r] = marks
            recs.append((d.get('ballot'), d['contest'].strip(), ranks))
    return meta, recs


def main(inp, outp):
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    cvr = os.path.join(inp, 'cvr')
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        meta, recs = read_batch(p)
        b = str(meta.get('batch'))
        rev = int(str(meta.get('revision')).strip())
        if b not in best or rev > best[b][0]:
            best[b] = (rev, str(meta.get('status', '')).strip().lower(), recs)
    by_contest = {}
    for rev, status, recs in best.values():
        if status == 'void':
            continue
        for ballot, contest, ranks in recs:
            by_contest.setdefault(contest, []).append(ranks)

    out = {'election': el['election'], 'contests': []}
    for c in el['contests']:
        out['contests'].append(count(c, by_contest.get(c['id'], [])))
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=1)


def count(c, records):
    maxr = c['max_ranks']
    names = {}  # normalized id -> output id
    withdrawn = set()
    for cd in c['candidates']:
        names[norm_id(cd['id'])] = cd['id']
        if cd.get('status') == 'withdrawn':
            withdrawn.add(norm_id(cd['id']))
    wi = {}
    for w in c.get('write_ins', []):
        names[norm_id(w['id'])] = w['id']
        for t in [w['name']] + list(w.get('aliases', [])):
            wi[norm_text(t)] = norm_id(w['id'])
    lot = [norm_id(x) for x in c.get('lot_order', [])]
    cands = [k for k in names if k not in withdrawn]

    # read ballots -> list of rankings: ('skip',) / ('pass',) / ('over',) / ('choice', id)
    ballots = []
    for ranks in records:
        seen = set()
        rl = []
        for r in range(1, maxr + 1):
            marks = set()
            for kind, v in ranks.get(r, []):
                if kind == 'w':
                    k = wi.get(norm_text(v))
                    if k is not None:
                        marks.add(k)
                else:
                    marks.add(norm_id(v))
            if not marks:
                rl.append('skip')
                continue
            marks -= withdrawn
            if not marks:
                rl.append('pass')
                continue
            before = set(marks)
            marks -= seen
            seen |= before
            if not marks:
                rl.append('skip')
            elif len(marks) == 1:
                rl.append(next(iter(marks)))
            else:
                rl.append('over')
        ballots.append(rl)

    def read(rl, cont):
        n = len(rl)
        for i, s in enumerate(rl):
            if s == 'pass' or s == 'over':
                continue
            if s == 'skip':
                if i + 1 >= n or rl[i + 1] == 'skip':
                    return None
                continue
            if s in cont:
                return s
        return None

    res = {'contest': c['id'], 'ballots': len(ballots), 'winner': None, 'rounds': []}
    cont = set(cands)
    hist = []
    rn = 0
    while True:
        rn += 1
        t = {k: 0 for k in cont}
        active = 0
        for rl in ballots:
            k = read(rl, cont)
            if k is not None:
                t[k] += 1
                active += 1
        hist.append(t)
        rd = {'round': rn, 'tallies': {names[k]: v for k, v in t.items()},
              'exhausted': len(ballots) - active, 'eliminated': []}
        res['rounds'].append(rd)
        if active == 0:
            break
        win = [k for k, v in t.items() if v * 2 > active]
        if not win and len(cont) == 1:
            win = list(cont)
        if win:
            res['winner'] = names[win[0]]
            break
        zeros = [k for k, v in t.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(t.values())
            tied = [k for k, v in t.items() if v == m]
            j = rn - 2
            while len(tied) > 1 and j >= 0:
                mm = min(hist[j][k] for k in tied)
                tied = [k for k in tied if hist[j][k] == mm]
                j -= 1
            if len(tied) > 1:
                tied.sort(key=lambda k: lot.index(k) if k in lot else -1)
                tied = [tied[-1]]
            elim = tied
        rd['eliminated'] = sorted(names[k] for k in elim)
        cont -= set(elim)
    return res


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
